#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
typedef struct{const char*s;int p;} P;
static void grow(char**b,int*cap,int need){while(*cap<need)*cap*=2;*b=realloc(*b,*cap);}
static void add(char**b,int*l,int*cap,const char*x,int n){grow(b,cap,*l+n+1);memcpy(*b+*l,x,n);*l+=n;(*b)[*l]=0;}
static char* parse(P*p,int*out){int cap=64,l=0;char*r=malloc(cap);
while(p->s[p->p]&&p->s[p->p]!=']'){if(islower((unsigned char)p->s[p->p])){add(&r,&l,&cap,p->s+p->p,1);p->p++;}
else{int k=0;while(isdigit((unsigned char)p->s[p->p])){k=k*10+p->s[p->p]-'0';p->p++;}p->p++;int il=0;char*in=parse(p,&il);p->p++;grow(&r,&cap,l+il*k+1);for(int j=0;j<k;j++){memcpy(r+l,in,il);l+=il;}r[l]=0;free(in);}}*out=l;return r;}
char*decodeString(char*s){P p={s,0};int n;return parse(&p,&n);}

