class Solution{public String decodeString(String s){Deque<Integer> c=new ArrayDeque<>();Deque<StringBuilder> st=new ArrayDeque<>();StringBuilder cur=new StringBuilder();int n=0;
for(int i=0;i<s.length();i++){char ch=s.charAt(i);if(Character.isDigit(ch))n=n*10+ch-'0';else if(ch>='a'&&ch<='z')cur.append(ch);
else if(ch=='['){c.push(n);st.push(cur);n=0;cur=new StringBuilder();}else{int r=c.pop();StringBuilder p=st.pop();for(int k=0;k<r;k++)p.append(cur);cur=p;}}return cur.toString();}}

