import sys,json
class Solution:
    def decodeString(self,s):
        counts=[]; strings=[]; cur=[]; num=0
        for ch in s:
            if ch.isdigit(): num=num*10+int(ch)
            elif ch.isalpha(): cur.append(ch)
            elif ch=="[":
                counts.append(num); strings.append(cur); num=0; cur=[]
            else:
                cur=strings.pop()+cur*counts.pop()
        return "".join(cur)
for line in sys.stdin:
    a=json.loads(line); print(json.dumps(Solution().decodeString(a[0])))

